<script>document.querySelectorAll('.preview-step').forEach(button=>button.addEventListener('click',()=>{const form=button.closest('form');const values={first_name:'Alex',business_name:'Acme Dental',city:'Austin',state:'TX',category:'Dentists',website:'https://example.com'};const render=text=>Object.entries(values).reduce((value,[key,replacement])=>value.replaceAll('{'.repeat(2)+key+'}'.repeat(2),replacement),text);const preview=form.querySelector('.step-preview');preview.textContent=render(form.querySelector('.step-subject').value)+'\n\n'+render(form.querySelector('.step-body').value);preview.classList.remove('hidden');}));</script></x-app-layout>
